use vstd::prelude::*;

verus! {

    // A specification function that characterizes when a sequence of chars
    // is non‐empty and all in the range 'a'..='z'.
    spec fn is_all_lowercase(s: Seq<char>) -> bool {
        s.len() > 0
        &&
        forall|i: nat| i < s.len() ==> s[i] >= 'a' && s[i] <= 'z'
    }

    // Runtime function: checks the same property on a Vec<char>.
    fn check_all_lowercase(v: &Vec<char>) -> bool
        ensures
            // The return value exactly matches the spec predicate on the view v@
            result == is_all_lowercase(v@),
    {
        let len: usize = v.len();
        if len == 0 {
            // empty vector ⇒ not "all lowercase"
            return false;
        }
        let mut idx: usize = 0;
        // We know len > 0 from above
        while idx < len
            invariant
                idx <= len,
                // Every index < idx has been seen to be in 'a'..='z'
                forall|j: nat| j < (idx as nat) ==>
                    (v@)[j] >= 'a' && (v@)[j] <= 'z',
            decreases len - idx,
        {
            let c: char = v[idx];
            if c < 'a' || c > 'z' {
                // early exit on first non‐lowercase
                return false;
            }
            idx = idx + 1;
        }
        // At this point idx == len and len > 0 and all v@[0..len) are lowercase
        assert(is_all_lowercase(v@));  
        true
    }

    // The main solve function.
    // If and only if the input is non‐empty and all lowercase, return ['a'],
    // otherwise return ['A'].
    fn solve(input: Vec<char>) -> Vec<char>
        ensures
            result.len() == 1,
            // the returned single character is 'a' exactly when
            // the input meets the "all lowercase" predicate
            check_all_lowercase(&input) ==> result[0] == 'a',
            !check_all_lowercase(&input) ==> result[0] == 'A',
            // furthermore, the result is one of the two allowed arrays
            result == vec!['a'] || result == vec!['A'],
    {
        if check_all_lowercase(&input) {
            vec!['a']
        } else {
            vec!['A']
        }
    }
}

